static const ystr S1566 = { 2307, "\012\012@(private) module view-host {\012    // std's view-nodes.Dom, its funcs this program's dom's\012    host: func() -> view-nodes.Dom {\012        {\012            comment: { content: string -> dom.create-comment(content) },\012            insert: { parent: u32, node: u32, before: u32 -> dom.insert-before(parent, node, before); },\012            append: { parent: u32, node: u32 -> dom.append-child(parent, node); },\012            remove: { node: u32 -> dom.remove(node); },\012            element: { tag: string -> dom.create-element(tag) },\012            text: { content: string -> dom.create-text(content) },\012            attribute: { node: u32, name: string, value: view-nodes.Value -> dom.set-attribute(node, name, host-value(value)); },\012            style: { node: u32, name: string, value: view-nodes.Value -> dom.set-style(node, name, host-value(value)); },\012            set-text: { node: u32, content: string -> dom.set-text-content(node, content); },\012        }\012    }\012\012    // a value as the host takes it\012    host-value: func(v: view-nodes.Value) -> dom.attribute-value {\012        match v {\012            text(x) => dom.attribute-value.str(x),\012            flag(x) => dom.attribute-value.%bool(x),\012            whole(x) => dom.attribute-value.%s32(x),\012            real(x) => dom.attribute-value.%f64(x),\012        }\012    }\012\012    // a style's value as the host takes it\012    style-value: func(v: string | bool | s32 | f64 | dom.color) -> dom.attribute-value {\012        match v {\012            let x: string => dom.attribute-value.str(x),\012            let x: bool => dom.attribute-value.%bool(x),\012            let x: s32 => dom.attribute-value.%s32(x),\012            let x: f64 => dom.attribute-value.%f64(x),\012            let x: dom.color => dom.attribute-value.color(x),\012        }\012    }\012\012    // a style set once\012    style: func(node: u32, name: string, v: string | bool | s32 | f64 | dom.color) { dom.set-style(node, name, style-value(v)); }\012\012    // a style kept current: read, set, and set again each time what it reads changes to a value\012    // it was not\012    keep-style: func(node: u32, name: string, read: func() -> string | bool | s32 | f64 | dom.color) {\012        let last = read();\012        dom.set-style(node, name, style-value(last));\012        reactive.watch(read, last, { now -> dom.set-style(node, name, style-value(now)); });\012    }\012}\012" };
